		n: i32 = 0
		for i in 0..<len(t.node_alive) {
			if !t.node_alive[i] || t.node_kind[i] != .Terminal {
				continue
			}
			if map_district_assign(board, t.node_pos[i]) == d {
				n += 1
			}
		}
		return n
	}
